$s=$s.Replace('function deleteExam(id){if(!confirm(','function deleteExam(id){if(!confirm(')
$s=$s.Replace("function deleteExam(id){if(!confirm('Hapus ujian beserta bank soal mapel tersebut?'))return;const exams=get('axo_exams',[]),e=exams.find(x=>x.id===id);const remaining=exams.filter(x=>x.id!==id);set('axo_exams',remaining);if(!remaining.some(x=>x.subject===e.subject))set('axo_questions',get('axo_questions',[]).filter(q=>q.subject!==e.subject));renderExamAdmin($('operatorContent'));toast('Ujian dan data mapelnya dihapus',true)}","function deleteExam(id){if(!confirm('Hapus ujian ini beserta bank soal, nilai, sesi, dan pelanggaran mapelnya?'))return;const exams=get('axo_exams',[]),e=exams.find(x=>x.id===id);if(!e)return;const remaining=exams.filter(x=>x.id!==id);set('axo_exams',remaining);set('axo_results',get('axo_results',[]).filter(r=>r.examId!==id&&!(!remaining.some(x=>x.subject===e.subject)&&r.subject===e.subject)));set('axo_sessions',get('axo_sessions',[]).filter(s=>s.examId!==id&&!(!remaining.some(x=>x.subject===e.subject)&&s.subject===e.subject)));set('axo_violations',get('axo_violations',[]).filter(v=>v.examId!==id&&!(!remaining.some(x=>x.subject===e.subject)&&v.subject===e.subject)));if(!remaining.some(x=>x.subject===e.subject)){set('axo_questions',get('axo_questions',[]).filter(q=>q.subject!==e.subject))}renderExamAdmin($('operatorContent'));toast('Ujian, mapel, bank soal, dan nilai terkait dihapus',true)}")

$scores=@'
function renderScores(el){const exams=get('axo_exams',[]),results=get('axo_results',[]),selected=window.scoreSubject||exams[0]?.subject||'',filtered=results.filter(r=>!selected||r.subject===selected);el.innerHTML=`<div class="pageHead"><div><h1>Rekap Nilai / Spreadsheet</h1><p>Nilai peserta direkap otomatis per mata pelajaran</p></div><button class="btn btnGreen" onclick="exportScores()">⇩ Ekspor Spreadsheet</button></div><div class="subjectTabs">${exams.map(e=>`<button class="${e.subject===selected?'active':''}" onclick="window.scoreSubject='${esc(e.subject)}';opPage('scores')">${esc(e.subject)}</button>`).join('')}</div><div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><div class="statTop">Peserta dinilai <b>RESULT</b></div><strong>${filtered.length}</strong></div><div class="stat"><div class="statTop">Nilai rata-rata <b>MEAN</b></div><strong>${filtered.length?Math.round(filtered.reduce((a,r)=>a+r.score,0)/filtered.length):'-'}</strong></div><div class="stat"><div class="statTop">Nilai tertinggi <b>MAX</b></div><strong>${filtered.length?Math.max(...filtered.map(r=>r.score)):'-'}</strong></div></div><div class="card" style="margin-top:10px;overflow-x:auto"><table class="table"><thead><tr><th>Nama Peserta</th><th>Username</th><th>Ujian</th><th>Mapel</th><th>Jawaban Benar</th><th>Nilai</th><th>Pengiriman</th><th>Waktu Selesai</th></tr></thead><tbody>${filtered.length?filtered.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td class="mono">${esc(r.username)}</td><td>${esc(r.title)}</td><td>${esc(r.subject)}</td><td>${r.correct}/${r.total}</td><td><span class="badge">${r.score}</span></td><td><span class="badge ${r.forced?'warn':''}">${r.forced?'Paksa':'Manual'}</span></td><td class="mono">${r.finished?new Date(r.finished).toLocaleString('id-ID'): '-'}</td></tr>`).join(''):'<tr><td colspan="8" style="text-align:center;color:var(--muted)">Belum ada nilai untuk mapel ini</td></tr>'}</tbody></table></div>`}
function exportScores(){const selected=window.scoreSubject||get('axo_exams',[])[0]?.subject||'',rows=get('axo_results',[]).filter(r=>!selected||r.subject===selected).map(r=>({Nama:r.name,Username:r.username,Ujian:r.title,Mapel:r.subject,'Jawaban Benar':`${r.correct}/${r.total}`,Nilai:r.score,Pengiriman:r.forced?'Paksa':'Manual','Waktu Selesai':r.finished?new Date(r.finished).toLocaleString('id-ID'):''}));if(!rows.length)return toast('Belum ada nilai yang dapat diekspor.',true);if(window.XLSX){const wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'Rekap Nilai');XLSX.writeFile(wb,`rekap-${selected||'nilai'}-${new Date().toISOString().slice(0,10)}.xlsx`);toast('Rekap nilai berhasil diekspor ke XLSX')}else{const cols=Object.keys(rows[0]),csv=[cols.join(','),...rows.map(row=>cols.map(c=>`"${String(row[c]??'').replace(/"/g,'""')}"`).join(','))].join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`rekap-${selected||'nilai'}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Rekap nilai berhasil diekspor ke Spreadsheet CSV')}}
'@
