$start=$s.IndexOf('function networkStatus(){return navigator.onLine')
$end=$s.IndexOf('function startExamFromInput(id)', $start)
if($start -ge 0 -and $end -gt $start){
$participant=@'
function networkStatus(){return navigator.onLine?'ONLINE':'OFFLINE'}function participantDashboardClock(){return new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}function renderParticipant(){clearInterval(liveTick);const results=get('axo_results',[]).filter(r=>r.username===activeUser.username);$('app').innerHTML=`<div class="participantApp"><header class="participantNav"><div class="participantBrand"><div class="brandLogo">AX</div><div><b>AxoExam</b><small>peserta://runtime</small></div></div><div class="participantTools"><span class="badge ${navigator.onLine?'':'red'}">● ${networkStatus()}</span><button class="navTool" onclick="openNetworkSettings()">⌁ <span>Jaringan</span></button><div class="clock participantClock">◷ <span id="participantClock"></span></div></div><div class="participantIdentity"><div class="avatar">${esc(activeUser.name?.charAt(0)||'P')}</div><div><b>${esc(activeUser.name)}</b><small>${esc(activeUser.class||'-')} · ${esc(activeUser.username)}</small></div><button class="btn btnDanger" onclick="logout()">Keluar</button></div></header><main class="content participantContent"><div class="pageHead"><div><h1>Dashboard Peserta</h1><p>Assessment workspace · semua data diperbarui realtime</p></div><span class="live"><i></i> SESSION SECURE</span></div><div class="stats"><div class="stat"><div class="statTop">Mapel tersedia <b>EXAM</b></div><strong>${get('axo_exams',[]).length}</strong></div><div class="stat"><div class="statTop">Ujian selesai <b>SYNC</b></div><strong>${results.length}</strong></div><div class="stat"><div class="statTop">Nilai rata-rata <b>MAPEL</b></div><strong>${results.length?Math.round(results.reduce((a,r)=>a+r.score,0)/results.length):'-'}</strong></div><div class="stat"><div class="statTop">Status jaringan <b>${networkStatus()}</b></div><strong style="font-size:20px">${navigator.connection?.effectiveType||'Browser'}</strong></div></div><div class="card participantExamCard"><div class="cardHead"><div><h3>Daftar Ujian & Nilai Mapel</h3><p>Pilih ujian dan masukkan token yang diberikan operator</p></div></div><div class="examTableWrap"><table class="table"><thead><tr><th>Ujian</th><th>Mata Pelajaran</th><th>Durasi</th><th>Nilai</th><th>Token</th><th>Aksi</th></tr></thead><tbody>${get('axo_exams',[]).map(e=>{const done=results.find(r=>r.examId===e.id);return `<tr><td><b>${esc(e.title)}</b></td><td><span class="subjectChip">${esc(e.subject)}</span></td><td>${e.duration} menit</td><td><span class="badge ${done?'':'warn'}">${done?done.score:'Belum dikerjakan'}</span></td><td>${done?'Selesai':`<input id="token_${e.id}" class="search examTokenInput" placeholder="Token mapel">`}</td><td>${done?'':`<button class="btn btnPrimary startBtn" onclick="startExamFromInput('${e.id}')">Mulai Ujian →</button>`}</td></tr>`}).join('')||'<tr><td colspan="6" style="text-align:center;color:var(--muted)">Belum ada ujian aktif</td></tr>'}</tbody></table></div></div></main></div>`;liveTick=setInterval(()=>{const c=document.getElementById('participantClock');if(c)c.textContent=participantDashboardClock();if(activeRole==='participant')renderParticipantClockOnly()},1000)}function renderParticipantClockOnly(){const c=document.getElementById('participantClock');if(c)c.textContent=participantDashboardClock()}function openNetworkSettings(){if(location.protocol==='http:')toast('Jaringan browser tidak dapat mengubah koneksi Wi-Fi perangkat. Buka pengaturan Windows/Android untuk mengubah Wi-Fi.',true);else try{location.href='ms-settings:network-wifi'}catch(e){toast('Buka pengaturan jaringan perangkat untuk mengubah Wi-Fi.',true)}}
'@
$s=$s.Substring(0,$start)+$participant+$s.Substring($end)
}

