$css=@'
.participantApp{min-height:100vh;background:#07111f}.participantNav{height:78px;position:sticky;top:0;z-index:30;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:18px;padding:0 24px;background:rgba(9,20,38,.96);border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}.participantBrand{display:flex;align-items:center;gap:10px}.participantBrand>div:last-child{display:grid}.participantBrand small,.participantIdentity small{font:10px "JetBrains Mono";color:var(--muted);margin-top:3px}.participantTools{justify-self:center;display:flex;align-items:center;gap:8px}.navTool{height:38px;border:1px solid var(--line);border-radius:6px;background:var(--panel2);padding:0 10px;font-weight:800}.participantIdentity{display:flex;align-items:center;gap:8px}.participantIdentity>div:nth-child(2){display:grid}.participantIdentity b{font-size:12px}.participantContent{max-width:1320px}.cardHead{display:flex;justify-content:space-between}.cardHead h3{margin-bottom:4px!important}.cardHead p{margin:0;color:var(--muted);font-size:11px}.participantExamCard{margin-top:12px;overflow:hidden}.examTableWrap{overflow-x:auto}.examTokenInput{width:150px!important;height:36px!important}.subjectChip{display:inline-flex;border:1px solid rgba(77,199,255,.2);background:rgba(77,199,255,.07);color:var(--cyan);border-radius:5px;padding:6px 8px;font:700 10px "JetBrains Mono"}.startBtn{white-space:nowrap}
@media(max-width:1100px){.shell{grid-template-columns:190px 1fr}.stats{grid-template-columns:repeat(2,1fr)}.participantNav{grid-template-columns:auto 1fr auto;gap:8px}.participantIdentity>div:nth-child(2){display:none}.navTool span{display:none}}
@media(max-width:760px){body{font-size:14px}.shell{display:block}.sidebar{position:fixed;z-index:50;left:0;right:0;bottom:0;top:auto;height:auto;padding:7px;background:rgba(9,20,38,.98);border-right:0;border-top:1px solid var(--line)}.sidebar .brand,.sidebar .build{display:none}.nav{grid-template-columns:repeat(6,1fr);gap:3px}.nav button{height:50px;padding:4px;text-align:center;font-size:9px;overflow:hidden}.nav button span{display:block;margin:0 0 2px}.nav button.active{box-shadow:inset 0 2px var(--green)}.shell>div{padding-bottom:64px}.topbar{height:58px;padding:0 12px}.topbar>.topRight .live{display:none}.clock{height:34px}.content{padding:16px 12px 28px}.pageHead{align-items:flex-start}.pageHead h1{font-size:20px}.stats{grid-template-columns:repeat(2,1fr)}.stat{min-height:96px;padding:12px}.grid2{grid-template-columns:1fr}.formGrid{grid-template-columns:1fr}.login{grid-template-columns:1fr}.loginVisual{display:none}.loginSide{min-height:100vh;padding:20px}.loginCard{width:100%;max-width:430px}.table{min-width:720px}.participantNav{height:auto;min-height:68px;padding:10px 12px;grid-template-columns:auto 1fr}.participantBrand small{display:none}.participantTools{justify-self:end}.participantTools .clock{display:none}.participantIdentity{grid-column:1/-1;width:100%;border-top:1px solid var(--line);padding-top:9px}.participantIdentity>div:nth-child(2){display:grid}.participantIdentity .btn{margin-left:auto}.participantContent{padding-top:16px}.examTableWrap .table{min-width:760px}.subjectTabs{padding-bottom:3px}.toast{right:12px;top:76px;width:calc(100vw - 24px)}}
@media(max-width:420px){.stats{grid-template-columns:1fr 1fr}.participantTools .badge{font-size:8px}.participantBrand b{font-size:13px}.nav button{font-size:8px}.pageHead{gap:8px}.pageHead>.live{display:none}.modal{padding:15px}}
'@
